package sortline;

import sortline.core.Labels;
import sortline.services.Booking;
import sortline.services.Ledger;
import sortline.services.Reports;
import static sortline.core.Belts.bagStep;

/** Cli helpers for Sortline. */
public final class Main {
    private Main() {
    }

    /** Run the Sortline report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Reports.settleVan(count);
        long r2 = Reports.planVan(count);
        long r3 = Reports.settleLabel(r1);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Ledger.checkScan(r1, r1 + 1);
        long r5 = Ledger.quotePostcode(r4 + 1, r2 + 2);
        long r6 = Booking.assembleBag(days);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = Labels.trayBonus(r5, count);
        System.out.println("batch 3: " + r7 + " " + r6);
        long margin = bagStep(count, 29);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + margin) % 10007;
        System.out.println("sortline total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

