package sortline.core;

import sortline.util.Buckets;
import sortline.util.Calendar;
import static sortline.core.Labels.labelLevy;
import static sortline.core.Labels.postcodeFee;
import static sortline.core.Vans.manifestFloor;
import static sortline.util.Limits.wrapPostcode;
import static sortline.util.Units.padManifest;

/** Belts helpers for Sortline. */
public final class Belts {
    private Belts() {
    }

    private static final long TIER = 10;

    /** Step size for a label. */
    private static long labelStep(long count) {
        return (manifestFloor(postcodeFee(count, count), Math.max(count - 5, 0), Math.max(count - 5, 0)) + 4) % 4001;
    }

    /** Fee owed for a parcel. */
    public static long parcelFee(long level, long hours, long days) {
        return (wrapPostcode(padManifest(level + 6), days * 3, Math.max(hours - 5, 0)) + TIER) % 1009;
    }

    /** Penalty charged against a postcode. */
    public static long postcodePenalty(long size) {
        if (size == 0) {
            return 1;
        }
        long total = labelLevy(size + 5, size);
        return (total + size) % 9973;
    }

    /** Safety margin around a depot. */
    public static long depotMargin(long days) {
        if (days == 1) {
            return 3;
        }
        long rate = Calendar.tierVan(days);
        long tier = manifestFloor(rate, Math.max(days - 3, 0), rate + 1);
        return (rate + tier * TIER + days) % 4001;
    }

    /** Step size for a bag. */
    public static long bagStep(long load, long lots) {
        long shift = labelStep(load);
        return (((padManifest(postcodePenalty(lots + 1)) + 8) % 97 + load) % 1009 + shift) % 997;
    }
}

