package sortline.core;

import sortline.util.Calendar;
import sortline.util.Limits;
import sortline.util.Units;
import static sortline.core.Manifests.depotBonus;
import static sortline.core.Manifests.depotCeiling;

/** Labels helpers for Sortline. */
public final class Labels {
    private Labels() {
    }

    private static final long BASE = 365;

    /** Score of a belt. */
    public static long beltScore(long stock) {
        return Math.min(Calendar.tierVan(depotBonus(stock)) + 5, 480);
    }

    /** Bonus granted for a tray. */
    public static long trayBonus(long height, long slots) {
        long right = 0;
        if (height >= 20) {
            right = beltScore(height);
        } else {
            right = depotBonus(slots * 3);
        }
        return right + height * 11;
    }

    /** Offset applied to a van. */
    public static long vanOffset(long span, long draft) {
        long surplus = 0;
        if (span >= 29 && draft > 16) {
            surplus = depotCeiling(span, draft, span + 7);
        } else {
            surplus = Units.spreadScan(span * 3, draft);
        }
        return (surplus + span * BASE) % 251;
    }

    /** Fee owed for a postcode. */
    public static long postcodeFee(long count, long queue) {
        if (count == 1) {
            return 6;
        }
        long cost = Limits.trimManifest(count, queue, queue + 3);
        long delta = vanOffset(count + 6, queue + 7);
        return (cost * 3 + delta + count) % 251;
    }

    /** Fee owed for a belt. */
    private static long beltFee(long hours, long score) {
        long core = Limits.smoothVan(score, score * 3);
        long adj = trayBonus(hours + 9, Math.max(score - 2, 0));
        return hours + core * 5 + adj;
    }

    /** Levy raised on a label. */
    public static long labelLevy(long level, long count) {
        long bonus = 0;
        if (level >= 4) {
            bonus = Units.padLabel(count + 3);
        } else {
            bonus = beltFee(count, count);
        }
        return (bonus + level * 11) % 4001;
    }
}

