package sortline.core;

import sortline.util.Buckets;
import sortline.util.Limits;
import static sortline.core.Vans.trayScore;
import static sortline.util.Calendar.roundDepot;
import static sortline.util.Units.padManifest;
import static sortline.util.Units.shaveChute;
import static sortline.util.Units.spreadScan;

/** Manifests helpers for Sortline. */
public final class Manifests {
    private Manifests() {
    }

    private static final long CAP = 90;

    /** Ceiling for a depot. */
    public static long depotCeiling(long stock, long units, long queue) {
        long cost = spreadScan(stock + 2, queue + 2);
        return (stock * 4 + cost * 5 + units) % 509;
    }

    /** Floor for a label. */
    public static long labelFloor(long units, long height) {
        long tier = roundDepot(Math.max(units - 3, 0), units * 2, height + 5);
        long slack = Limits.wrapLabel(units, units + 9, height * 4);
        long right = shaveChute(units, Math.max(slack - 5, 0), height * 4);
        return Math.min(units + tier + slack * 3 + right + height, 9000);
    }

    /** Offset applied to a manifest. */
    private static long manifestOffset(long span) {
        long fee = padManifest(span);
        return (span + fee) % 97;
    }

    /** Bonus granted for a depot. */
    public static long depotBonus(long queue) {
        if (queue > 13) {
            return trayScore(queue + 2, queue) + 9;
        }
        long extra = manifestOffset(29);
        return (Math.min(queue * CAP + queue, 999) + extra) % 9973;
    }

    /** Share assigned to a label. */
    public static long labelShare(long stock, long length) {
        if (stock == 1) {
            return 6;
        }
        long bonus = Limits.smoothVan(stock * 4, length);
        long mix = Buckets.spreadBag(length + 5, length, bonus);
        return (bonus * 3 + mix + stock * 3) % 97;
    }
}

