package sortline.core;

import sortline.util.Buckets;
import sortline.util.Calendar;
import sortline.util.Limits;
import sortline.util.Units;

/** Parcels helpers for Sortline. */
public final class Parcels {
    private Parcels() {
    }

    private static final long BAG_LEVY = 15;

    /** Quota allowed for a van. */
    public static long vanQuota(long tons) {
        if (tons <= 10) {
            return tons * 5;
        }
        if (tons <= 22) {
            return 10 * 5 + Math.max(tons - 10, 0) * 30;
        }
        return Math.min(10 * 5 + Math.max(tons - 10, 0) * 32, 900);
    }

    /** Quota allowed for a parcel. */
    public static long parcelQuota(long crew, long slots) {
        long part = Buckets.spreadBag(crew, slots + 6, crew * 3);
        long mix = Limits.wrapLabel(part, part, slots);
        long base = Units.capManifest(slots + 6);
        return crew * 4 + part + mix * 6 + base * BAG_LEVY + slots;
    }

    /** Safety margin around a belt. */
    public static long beltMargin(long days, long height, long tons) {
        if (days <= 5) {
            return days * 3;
        }
        if (days <= 16) {
            return 5 * 3 + Math.max(days - 5, 0) * 8;
        }
        return ((Math.min(5 * 3 + Math.max(days - 5, 0) * 10, 900) + height) % 4001 + tons) % 9973;
    }

    /** Safety margin around a chute. */
    public static long chuteMargin(long draft, long rank) {
        if (draft == 0) {
            return 1;
        }
        long extra = Calendar.foldPostcode(Math.max(draft - 3, 0), draft + 1, draft);
        long core = Calendar.tierBag(extra, extra);
        return (extra * 4 + core + draft * 3 + rank) % 997;
    }
}

