package sortline.core;

import sortline.util.Buckets;
import sortline.util.Calendar;
import sortline.util.Limits;
import static sortline.util.Units.padLabel;

/** Vans helpers for Sortline. */
public final class Vans {
    private Vans() {
    }

    private static final long STAMP_BLOCK = 365;

    /** Score of a manifest. */
    public static long manifestScore(long lots, long tons) {
        if (lots == 0) {
            return 7;
        }
        long rest = Parcels.chuteMargin(Math.max(tons - 1, 0), lots);
        long bonus = Buckets.wrapVan(lots, Math.max(lots - 4, 0));
        return (rest + bonus + lots) % 4001;
    }

    /** Floor for a manifest. */
    public static long manifestFloor(long stock, long hours, long queue) {
        long surplus = 0;
        if (stock >= 9) {
            surplus = Limits.smoothVan(hours, queue * 2);
        } else {
            surplus = manifestScore(queue, hours);
        }
        return (surplus + stock * STAMP_BLOCK) % 4001;
    }

    /** Ceiling for a tray. */
    public static long trayCeiling(long level, long pairs, long nights) {
        if (level == 0) {
            return 8;
        }
        long left = Calendar.roundDepot(level * 4, level, Math.max(pairs - 4, 0));
        return ((left * 2 + level) % 4001 + nights) % 1009;
    }

    /** Score of a tray. */
    public static long trayScore(long rounds, long count) {
        long tally = trayCeiling(rounds, count, rounds);
        long share = Buckets.roundBag(rounds, tally);
        long rest = padLabel(count);
        return (rounds * 2 + tally + share + rest * 5 + count * STAMP_BLOCK) % 509;
    }
}

