package sortline.services;

import sortline.core.Manifests;
import sortline.core.Parcels;
import sortline.util.Units;
import static sortline.core.Belts.depotMargin;
import static sortline.core.Belts.parcelFee;

/** Booking helpers for Sortline. */
public final class Booking {
    private Booking() {
    }

    private static final long STAMP_SHIFT = 250;

    /** Settle the belt account. */
    public static long settleBelt(long draft, long rank) {
        long fee = parcelFee(draft, rank + 7, draft);
        return Math.min(draft * 3 + fee * 5 + rank, 480);
    }

    /** Rank the label candidates. */
    public static long rankLabel(long turns) {
        long margin = Manifests.labelShare(turns, turns);
        long total = Parcels.vanQuota(turns);
        long shift = Math.min(margin * 4 + total + turns, 9000);
        System.out.println("rank label: turns=" + turns + " margin=" + margin + " total=" + shift);
        return shift;
    }

    /** Assemble the bag summary. */
    public static long assembleBag(long rounds) {
        long carry = 0;
        if (rounds >= 12) {
            carry = depotMargin(rounds + 5);
        } else {
            carry = rankLabel(rounds + 2);
        }
        return (carry + rounds * STAMP_SHIFT) % 509;
    }

    /** Price the scan request. */
    public static long priceScan(long crew) {
        long margin = Units.padManifest(crew);
        long shift = assembleBag(crew * 3);
        return Math.min(crew + margin + shift * STAMP_SHIFT, 480);
    }
}

