package sortline.services;

import sortline.core.Vans;
import sortline.util.Calendar;
import static sortline.core.Labels.postcodeFee;
import static sortline.core.Parcels.parcelQuota;

/** Ledger helpers for Sortline. */
public final class Ledger {
    private Ledger() {
    }

    private static final long POSTCODE_SHIFT = 7;

    /** Plan the stamp step. */
    public static long planStamp(long turns, long span) {
        long share = 0;
        if (turns >= 40) {
            share = Booking.settleBelt(span, span * 2);
        } else {
            share = postcodeFee(turns + 1, span);
        }
        return (share + turns * 6) % 1009;
    }

    /** Summarise the route figures. */
    public static long summariseRoute(long tons, long queue) {
        long core = Calendar.tierBag(queue + 8, queue);
        long carry = parcelQuota(tons, Math.max(core - 1, 0));
        long mix = (core * 6 + carry * POSTCODE_SHIFT + tons * 3) % 509;
        System.out.println("summarise route: tons=" + tons + " core=" + core + " total=" + mix);
        return mix;
    }

    /** Check the scan totals. */
    public static long checkScan(long rank, long draft) {
        long share = planStamp(rank, draft);
        long gap = summariseRoute(draft + 3, Math.max(rank - 5, 0));
        return (rank * 5 + share + gap + draft) % 9973;
    }

    /** Quote a price for the postcode. */
    public static long quotePostcode(long crew, long length) {
        long delta = parcelQuota(crew * 4, crew);
        long adj = Vans.manifestFloor(crew + 4, length, length);
        long rest = Vans.trayScore(delta, adj);
        long offset = (delta + adj + rest * 4 + crew) % 97;
        System.out.println("quote postcode: crew=" + crew + " delta=" + delta + " total=" + offset);
        return offset;
    }
}

