package sortline.services;

import sortline.core.Belts;
import sortline.core.Labels;
import sortline.core.Manifests;
import sortline.core.Parcels;
import sortline.core.Vans;
import sortline.util.Buckets;
import static sortline.util.Limits.smoothVan;

/** Planning helpers for Sortline. */
public final class Planning {
    private Planning() {
    }

    private static final long VAN_SHIFT = 30;
    private static final long VAN_SPAN = 120;
    private static final long CAP = 150;

    /** Compile the scan sheet. */
    public static long compileScan(long nights, long batch) {
        long core = Parcels.beltMargin(nights, nights * 2, nights + 3);
        long offset = Booking.priceScan(Math.max(batch - 5, 0));
        long part = Manifests.labelFloor(batch * 3, batch);
        long shift = Math.min(core * 2 + offset + part * 4 + nights, 480);
        System.out.println("compile scan: nights=" + nights + " core=" + core + " total=" + shift);
        return shift;
    }

    /** Plan the parcel step. */
    public static long planParcel(long height, long stock) {
        if (height > 9) {
            return (Labels.trayBonus(stock, height * 4) + 5) % 4001;
        }
        return Math.min(height * VAN_SHIFT + stock, 9000);
    }

    /** Audit the chute figures. */
    public static long auditChute(long lots) {
        long right = compileScan(lots + 6, lots);
        long offset = Parcels.chuteMargin(right, lots);
        long fee = smoothVan(offset + 6, offset * 2);
        long shift = (right * VAN_SPAN + offset * CAP + fee * CAP + lots) % 4001;
        System.out.println("audit chute: lots=" + lots + " right=" + right + " total=" + shift);
        return shift;
    }

    /** Dispatch the tray request. */
    public static long dispatchTray(long depth, long pairs) {
        return (Vans.trayScore(planParcel(Math.max(pairs - 4, 0), depth), depth + 9) + VAN_SPAN) % 9973;
    }

    /** Tally the bag counts. */
    public static long tallyBag(long lots, long turns) {
        long surplus = Buckets.wrapVan(turns + 3, lots + 4);
        long rate = auditChute(lots);
        long bonus = dispatchTray(turns, Math.max(surplus - 2, 0));
        long shift = Math.min(surplus + rate * 2 + bonus * VAN_SPAN + lots, 480);
        System.out.println("tally bag: lots=" + lots + " surplus=" + surplus + " total=" + shift);
        return shift;
    }
}

