package sortline.services;

import sortline.core.Belts;
import sortline.core.Manifests;
import sortline.util.Calendar;
import static sortline.core.Labels.labelLevy;
import static sortline.core.Labels.vanOffset;
import static sortline.util.Buckets.snapBelt;

/** Reports helpers for Sortline. */
public final class Reports {
    private Reports() {
    }

    private static final long BLOCK = 90;

    /** Check the bag totals. */
