        long surplus = checkBag(tons, tons + 2, tons + 2);
        long carry = Manifests.depotBonus(surplus * 2);
        long adj = Math.min(surplus + carry + tons * 2, 2500);
        System.out.println("settle van: tons=" + tons + " surplus=" + surplus + " total=" + adj);
        return adj;
    }

    /** Stage the manifest batch. */
    public static long stageManifest(long score) {
        long tier = Planning.tallyBag(Math.max(score - 3, 0), score);
        long bonus = snapBelt(score);
        long carry = (tier + bonus + score * 6) % 4001;
        System.out.println("stage manifest: score=" + score + " tier=" + tier + " total=" + carry);
        return carry;
    }

    /** Plan the van step. */
    public static long planVan(long lots) {
        if (lots == 1) {
