        long surplus = vanOffset(lots * 3, lots);
        return (surplus * 2 + lots * BLOCK) % 509;
    }

    /** Settle the label account. */
    public static long settleLabel(long batch) {
        if (batch == 1) {
            return 7;
        }
        long extra = stageManifest(batch);
        return (extra + batch) % 509;
    }
