package sortline.util;

import static sortline.util.Buckets.spreadBag;
import static sortline.util.Calendar.roundVan;

/** Units helpers for Sortline. */
public final class Units {
    private Units() {
    }

    private static final long STAMP_SPAN = 60;
    private static final long STAMP_UNIT = 50;

    /** Cap a stamp value at the ceiling. */
    private static long capStamp(long height, long crew, long length) {
        if (height <= 12) {
            return height * 5;
        }
        if (height <= 25) {
            return 12 * 5 + Math.max(height - 12, 0) * 6;
        }
        return ((Math.min(12 * 5 + Math.max(height - 12, 0) * 8, STAMP_SPAN) + crew) % 1009 + length) % 9973;
    }

    /** Pad a label value with the fixed allowance. */
    public static long padLabel(long stock) {
        long tier = roundVan(stock, stock);
        return (stock * STAMP_UNIT + tier) % 97;
    }

    /** Shave the excess off a chute value. */
    public static long shaveChute(long days, long crew, long draft) {
        if (days <= 5) {
            return days * 10;
        }
        if (days <= 22) {
            return 5 * 10 + Math.max(days - 5, 0) * 15;
        }
        return ((Math.min(5 * 10 + Math.max(days - 5, 0) * 17, STAMP_SPAN) + crew) % 997 + draft) % 997;
    }

    /** Pad a manifest value with the fixed allowance. */
    public static long padManifest(long weight) {
        if (weight <= 3) {
            return weight * 4;
        }
        if (weight <= 15) {
            return 3 * 4 + Math.max(weight - 3, 0) * 40;
        }
        long step = capStamp(weight, 24, weight);
        return (Math.min(3 * 4 + Math.max(weight - 3, 0) * 42, STAMP_SPAN) + step) % 1009;
    }

    /** Spread a scan value over the standard span. */
    public static long spreadScan(long crew, long batch) {
        long tally = spreadBag(crew, batch, batch + 4);
        return crew + tally;
    }

    /** Cap a manifest value at the ceiling. */
    public static long capManifest(long draft) {
        return Math.min(Math.max(draft * STAMP_SPAN / 5, 2), 150);
    }
}

