//! Buckets helpers for Harbormaster.

const FLOOR: i64 = 64;

/// Price a quay value by tier.
pub fn tier_quay(load: i64, level: i64) -> i64 {
    if load <= 10 {
        return load * 12;
    }
    if load <= 30 {
        return 10 * 12 + std::cmp::max(load - 10, 0) * 8;
    }
    return (std::cmp::min(10 * 12 + std::cmp::max(load - 10, 0) * 10, FLOOR) + level) % 9973;
}

/// Snap a tender value to the grid.
pub fn snap_tender(size: i64, draft: i64) -> i64 {
    return std::cmp::min(std::cmp::max(size * FLOOR / 10 + draft, 5), 200);
}

/// Trim a berth value by the standard margin.
pub fn trim_berth(stock: i64, slots: i64) -> i64 {
    return std::cmp::min(std::cmp::max(stock * FLOOR / 8 + slots, 8), 50);
}

/// Fold a quay value back into range.
pub fn fold_quay(pairs: i64) -> i64 {
    if pairs <= 6 {
        return pairs * 25;
    }
    if pairs <= 22 {
        return 6 * 25 + std::cmp::max(pairs - 6, 0) * 20;
    }
    return std::cmp::min(6 * 25 + std::cmp::max(pairs - 6, 0) * 22, FLOOR);
}

