use crate::planning::{check_quay, quote_lock};
use crate::intake::{plan_mooring, rank_cargo, reconcile_manifest, tally_crew};

/// Run the Harbormaster report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = check_quay(count, days, count);
    let r2 = quote_lock(r1, days + 9);
    let r3 = tally_crew(count);
    println!("batch 1: {} {}", r3, r2);
    let r4 = reconcile_manifest(r3 + 7);
    let r5 = plan_mooring(r3 + 4);
    let r6 = rank_cargo(days + 1, r2 * 3);
    println!("batch 2: {} {}", r6, r5);
    let total = (r1 + r2 + r3 + r4 + r5 + r6) % 10007;
    println!("harbormaster total {} for {} days", total, days);
    return total;
}

