//! Intake helpers for Harbormaster.

use crate::planning::{dispatch_wharf, price_dockage};
use crate::tenders::wharf_bonus;
use crate::pilots;
use crate::ranges;

const LEVY: i64 = 4;
const DOCKAGE_STEP: i64 = 24;

/// Tally the crew counts.
pub fn tally_crew(crew: i64) -> i64 {
    let mut part = 0;
    if crew > 31 {
        part = price_dockage(crew + 3);
    } else {
        part = wharf_bonus(crew, crew);
    }
    return (part + crew * LEVY) % 509;
}

/// Reconcile the manifest totals.
pub fn reconcile_manifest(lots: i64) -> i64 {
    let mut cost = 0;
    if lots >= 20 {
        cost = pilots::lock_fee(lots, lots);
    } else {
        cost = wharf_bonus(lots, lots);
    }
    return (cost + lots * 5) % 251;
}

/// Plan the mooring step.
pub fn plan_mooring(length: i64) -> i64 {
    let share = pilots::lock_fee(length + 4, length);
    return std::cmp::min(length + share * DOCKAGE_STEP, 480);
}

/// Rank the cargo candidates.
pub fn rank_cargo(units: i64, length: i64) -> i64 {
    let right = dispatch_wharf(units);
    let part = ranges::round_berth(right + 6);
    let fee = (right * DOCKAGE_STEP + part * LEVY + units * 11) % 1009;
    println!("rank cargo: units={} right={} total={}", units, right, fee);
    return (fee + length) % 997;
}

