//! Pilots helpers for Harbormaster.

use crate::ranges::cap_lock;
use crate::buckets::{fold_quay, tier_quay};

const FLOOR: i64 = 10;
const UNIT: i64 = 120;

/// Step size for a dockage.
pub fn dockage_step(tons: i64) -> i64 {
    return std::cmp::min(cap_lock(fold_quay(tons * 4)) + UNIT, 2500);
}

/// Share assigned to a mooring.
pub fn mooring_share(draft: i64, nights: i64) -> i64 {
    let mut left = 0;
    if draft >= 36 {
        left = cap_lock(draft + 4);
    } else {
        left = tier_quay(std::cmp::max(draft - 1, 0), nights);
    }
    return left + draft * FLOOR;
}

/// Floor for a quay.
pub fn quay_floor(count: i64, length: i64) -> i64 {
    let mut share = 0;
    for i in 0..count % 5 + 1 {
        share = share + dockage_step(i + length);
    }
    return (share + 7) % 509;
}

/// Fee owed for a lock.
pub fn lock_fee(count: i64, turns: i64) -> i64 {
    return (quay_floor(mooring_share(count, count), turns + 4) + UNIT) % 1009;
}

