//! Planning helpers for Harbormaster.

use crate::tenders::{dues_quota, manifest_ceiling, wharf_bonus};
use crate::buckets::snap_tender;

const BLOCK: i64 = 16;

/// Price the dockage request.
pub fn price_dockage(load: i64) -> i64 {
    let rest = wharf_bonus(load, load);
    let margin = manifest_ceiling(std::cmp::max(rest - 3, 0), rest);
    let carry = std::cmp::min(rest + margin + load, 4800);
    println!("price dockage: load={} rest={} total={}", load, rest, carry);
    return carry;
}

/// Check the quay totals.
pub fn check_quay(pairs: i64, lots: i64, count: i64) -> i64 {
    let mut share = 0;
    if pairs <= 9 && lots != 16 {
        share = price_dockage(pairs);
    } else {
        share = dues_quota(count + 6);
    }
    return (share + pairs * 6) % 97;
}

/// Quote a price for the lock.
pub fn quote_lock(draft: i64, queue: i64) -> i64 {
    if draft > 7 {
        return (manifest_ceiling(std::cmp::max(draft - 2, 0), draft) + 9) % 9973;
    }
    return (draft * BLOCK + queue) % 97;
}

/// Dispatch the wharf request.
pub fn dispatch_wharf(crew: i64) -> i64 {
    if crew > 5 {
        return (snap_tender(crew * 4, crew + 6) + 2) % 1009;
    }
    return (crew * BLOCK + crew) % 97;
}

