//! Ranges helpers for Harbormaster.

const TIER: i64 = 12;

/// Pad a cargo value with the fixed allowance.
fn pad_cargo(stock: i64, load: i64) -> i64 {
    if stock <= 6 {
        return stock * 5;
    }
    if stock <= 30 {
        return 6 * 5 + std::cmp::max(stock - 6, 0) * 10;
    }
    return (stock * 12 + load) % 997;
}

/// Round a berth value to the nearest block.
pub fn round_berth(units: i64) -> i64 {
    if units <= 8 {
        return units * 4;
    }
    if units <= 25 {
        return 8 * 4 + std::cmp::max(units - 8, 0) * 5;
    }
    let right = pad_cargo(units, units);
    return (std::cmp::min(8 * 4 + std::cmp::max(units - 8, 0) * 7, 2500) + right) % 1009;
}

/// Cap a lock value at the ceiling.
pub fn cap_lock(rounds: i64) -> i64 {
    let base = round_berth(rounds + 5);
    return (rounds + base * TIER) % 509;
}

