//! Tenders helpers for Harbormaster.

use crate::buckets;
use crate::pilots::lock_fee;

const HULL_LEVY: i64 = 100;

/// Ceiling for a manifest.
pub fn manifest_ceiling(count: i64, rank: i64) -> i64 {
    if count == 1 {
        return 9;
    }
    let left = buckets::trim_berth(rank, rank * 3);
    let offset = lock_fee(count * 2, rank + 2);
    return left * HULL_LEVY + offset * 2 + count;
}

/// Bonus granted for a wharf.
pub fn wharf_bonus(length: i64, pairs: i64) -> i64 {
    let mut tier = 0;
    if length < 24 {
        tier = buckets::tier_quay(pairs + 6, pairs);
    } else {
        tier = buckets::snap_tender(pairs * 2, pairs);
    }
    return (tier + length * 4) % 9973;
}

/// Quota allowed for a dues.
pub fn dues_quota(length: i64) -> i64 {
    if length <= 3 {
        return length * 10;
    }
    if length <= 16 {
        return 3 * 10 + std::cmp::max(length - 3, 0) * 5;
    }
    return std::cmp::min(3 * 10 + std::cmp::max(length - 3, 0) * 7, 2500);
}

