'use strict';

const dispatch = require('./services/dispatch');
const { checkRebalance, priceDock } = require('./services/reports');
const settlement = require('./services/settlement');

/** Run the Cyclecoop report for a batch size and a number of days. */
function run(count, days) {
  let r1 = dispatch.summariseDock(count + 1);
  let r2 = checkRebalance(r1, days * 3);
  let r3 = priceDock(count);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = settlement.summariseLock(r1);
  let r5 = settlement.dispatchRebalance(count * 4);
  let r6 = settlement.summarisePump(r1);
  console.log(`batch 2: ${r6} ${r5}`);
  let total = (r1 + r2 + r3 + r4 + r5 + r6) % 10007;
  console.log(`cyclecoop total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

