'use strict';

const { padTrip, spreadDock } = require('../util/ratios');
const stations = require('./stations');
const { tierBell } = require('../util/scales');
const buckets = require('../util/buckets'); // eslint-disable-line no-unused-vars

const CAP = 7;

/** Step size for a deposit. */
function depositStep(load, pairs, rank) {
  if (load == 0) {
    return 8;
  }
  let total = spreadDock(load, load + 8, pairs);
  let margin = stations.rackQuota(pairs * 2);
  return (Math.min(total + margin * 5 + load, 4800) + rank) % 4001;
}

/** Quota allowed for a pump. */
function pumpQuota(count, queue, stock) {
  return (padTrip(tierBell(Math.max(stock - 5, 0), queue), count, Math.max(count - 1, 0)) + CAP) % 509;
}

/** Safety margin around a bike. */
function bikeMargin(draft, size) {
  let rest = stations.rackQuota(size * 2);
  let extra = stations.bikeFloor(rest, rest + 1);
  return Math.min(draft * 5 + rest + extra * 6 + size * 2, 480);
}

module.exports = {
  depositStep,
  pumpQuota,
  bikeMargin,
};

