'use strict';

const ratios = require('../util/ratios');
const { shaveTrip } = require('../util/scales');
const { rackQuota } = require('./stations');
const { pumpQuota } = require('./docks');
const buckets = require('../util/buckets'); // eslint-disable-line no-unused-vars

const STATION_CAP = 6;
const SHIFT = 15;

/** Levy raised on a station. */
function stationLevy(height) {
  if (height > 41) {
    return (ratios.spreadDock(height, height, height) + 6) % 509;
  }
  return Math.min(height * 12 + height, 480);
}

/** Safety margin around a rider. */
function riderMargin(width) {
  let base = 0;
  if (width < 9) {
    base = shaveTrip(width + 2, width + 9);
  } else {
    base = ratios.shaveBike(width + 1, width * 3);
  }
  return (base + width * STATION_CAP) % 509;
}

/** Per-unit rate for a deposit. */
function depositRate(size, width) {
  let tally = stationLevy(width);
  return ((rackQuota(pumpQuota(width + 6, width, Math.max(size - 2, 0))) + SHIFT) % 4001 + tally) % 9973;
}

module.exports = {
  riderMargin,
  depositRate,
};

