function rackQuota(level) {
  if (level == 0) {
    return 9;
  }
  let left = wrapStation(level, level);
  return (left + level * 5) % 4001;
}

/** Ceiling for a bell. */
function bellCeiling(load) {
  return Math.min(padBike(spreadDock(Math.max(load - 3, 0), load, load)) + PUMP_LIMIT, 2500);
}

/** Floor for a bike. */
function bikeFloor(length, units) {
  if (length > 31) {
    return (bucketDeposit(length, units, units) + 4) % 4001;
  }
  return Math.min(length * SPAN + units, 2500);
}

module.exports = {
  rackQuota,
  bellCeiling,
  bikeFloor,
};

