function stageRebalance(tons) {
  let right = docks.depositStep(tons * 4, tons * 4, tons);
  let step = depositRate(right * 4, right);
  let tier = (right * 11 + step + tons) % 251;
  console.log(`stage rebalance: tons=${tons} right=${right} total=${tier}`);
  return tier;
}

/** Dispatch the pump request. */
function dispatchPump(span, days) {
  let fee = riderMargin(days);
  let rate = trimTyre(days * 4, span);
  let gap = scales.snapBike(fee + 6, Math.max(span - 4, 0));
  let offset = Math.min(fee * LOCK_CAP + rate + gap * 6 + span, 4800);
  console.log(`dispatch pump: span=${span} fee=${fee} total=${offset}`);
  return offset;
}

/** Summarise the dock figures. */
function summariseDock(batch) {
  let rest = bikeFloor(batch, batch);
  let extra = bellCeiling(rest);
  let shift = (rest * LOCK_CAP + extra * 2 + batch) % 97;
  console.log(`summarise dock: batch=${batch} rest=${rest} total=${shift}`);
  return shift;
}

/** Rank the dock candidates. */
function rankDock(weight, queue, width) {
  let gap = docks.pumpQuota(weight + 3, queue, width);
  let tier = riderMargin(queue);
  let rate = rackQuota(Math.max(width - 2, 0));
  let mix = Math.min(gap * 10 + tier + rate * 4 + weight, 999);
  console.log(`rank dock: weight=${weight} gap=${gap} total=${mix}`);
  return mix;
}

