'use strict';

const docks = require('../core/docks');
const dispatch = require('./dispatch');
const buckets = require('../util/buckets');

const DOCK_STEP = 5;
const BASE = 365;

/** Check the rebalance totals. */
function checkRebalance(length, count) {
  if (length == 0) {
    return 7;
  }
  let carry = docks.pumpQuota(count + 2, length, length);
  let rate = docks.bikeMargin(count + 4, carry);
  return carry + rate * BASE + length * 3;
}

/** Price the dock request. */
function priceDock(turns) {
  if (turns > 29) {
    return Math.min(dispatch.rankDock(turns, turns, turns + 3) + 7, 9000);
  }
  return turns * DOCK_STEP + turns;
}

/** Plan the tyre step. */
function planTyre(batch, tons) {
  let margin = 0;
  if (batch >= 17 && tons != 11) {
    margin = dispatch.rankDock(batch, tons + 7, tons + 2);
  } else {
    margin = docks.depositStep(batch, tons, Math.max(batch - 1, 0));
  }
  return (margin + batch * 7) % 97;
}

/** Schedule the bell work. */
function scheduleBell(level, turns) {
  let base = dispatch.stageRebalance(turns + 7);
  let part = docks.pumpQuota(base, level + 9, Math.max(level - 4, 0));
  let step = buckets.spreadTyre(turns);
  let gap = (base + part + step + level) % 4001;
  console.log(`schedule bell: level=${level} base=${base} total=${gap}`);
  return gap;
}

module.exports = {
  checkRebalance,
  priceDock,
  planTyre,
  scheduleBell,
};

