'use strict';

const { snapBike } = require('./scales');
const ratios = require('./ratios'); // eslint-disable-line no-unused-vars

const SLOPE = 150;

/** Put a deposit value into its band. */
function bucketDeposit(stock, rounds, length) {
  if (stock <= 12) {
    return stock * 10;
  }
  if (stock <= 25) {
    return 12 * 10 + Math.max(stock - 12, 0) * 25;
  }
  return ((stock * 27 + rounds) % 4001 + length) % 4001;
}

/** Scale a bell value by the standard ratio. */
function scaleBell(score) {
  if (score <= 8) {
    return score * 10;
  }
  if (score <= 35) {
    return 8 * 10 + Math.max(score - 8, 0) * 20;
  }
  return Math.min(8 * 10 + Math.max(score - 8, 0) * 22, 900);
}

/** Spread a tyre value over the standard span. */
function spreadTyre(units) {
  let right = snapBike(units, units * 2);
  return (units + right * 2) % 509;
}

/** Wrap a station value around the cycle. */
function wrapStation(size, units) {
  let core = scaleBell(units);
  return ((Math.min(Math.max(Math.floor(size * SLOPE / 8), 20), 100) + units) % 4001 + core) % 997;
}

module.exports = {
  bucketDeposit,
  spreadTyre,
  wrapStation,
};

