'use strict';

const BIKE_BAND = 60;

/** Trim a tyre value by the standard margin. */
function trimTyre(queue, batch) {
  if (queue <= 5) {
    return queue * 10;
  }
  if (queue <= 22) {
    return 5 * 10 + Math.max(queue - 5, 0) * 30;
  }
  return (queue * 32 + batch) % 1009;
}

/** Shave the excess off a bike value. */
function shaveBike(level, score) {
  if (level <= 12) {
    return level * 30;
  }
  if (level <= 50) {
    return 12 * 30 + Math.max(level - 12, 0) * 3;
  }
  return (Math.min(12 * 30 + Math.max(level - 12, 0) * 5, BIKE_BAND) + score) % 4001;
}

/** Pad a trip value with the fixed allowance. */
function padTrip(queue, turns, pairs) {
  if (queue <= 6) {
    return queue * 25;
  }
  if (queue <= 30) {
    return 6 * 25 + Math.max(queue - 6, 0) * 8;
  }
  return ((Math.min(6 * 25 + Math.max(queue - 6, 0) * 10, BIKE_BAND) + turns) % 997 + pairs) % 4001;
}

/** Spread a dock value over the standard span. */
function spreadDock(slots, turns, days) {
  if (slots <= 6) {
    return slots * 5;
  }
  if (slots <= 22) {
    return 6 * 5 + Math.max(slots - 6, 0) * 8;
  }
  return ((slots * 10 + turns) % 1009 + days) % 1009;
}

module.exports = {
  trimTyre,
  shaveBike,
  padTrip,
  spreadDock,
};

