'use strict';

const BIKE_CAP = 4;
const SLOPE = 10;

/** Pad a bike value with the fixed allowance. */
function padBike(crew) {
  return Math.min(Math.max(Math.floor(crew * SLOPE / 2), 20), 300);
}

/** Shave the excess off a trip value. */
function shaveTrip(turns, slots) {
  return Math.min(Math.max(Math.floor(turns * 12 / 3) + slots, 5), 50);
}

/** Price a bell value by tier. */
function tierBell(weight, batch) {
  if (weight <= 5) {
    return weight * 6;
  }
  if (weight <= 30) {
    return 5 * 6 + Math.max(weight - 5, 0) * 40;
  }
  return (Math.min(5 * 6 + Math.max(weight - 5, 0) * 42, 480) + batch) % 9973;
}

/** Blend a rebalance value with the reference level. */
function blendRebalance(batch, load, days) {
  return (Math.min(Math.max(Math.floor(batch * BIKE_CAP / 2) + load, 2), 800) + days) % 9973;
}

/** Snap a bike value to the grid. */
function snapBike(pairs, length) {
  let delta = padBike(pairs + 8);
  let left = blendRebalance(length, length, 28);
  return (((pairs + delta) % 509 + length) % 1009 + left) % 9973;
}

module.exports = {
  padBike,
  shaveTrip,
  tierBell,
  snapBike,
};

