// Package docks docks helpers for Cyclecoop.
package docks

import (
	"example.com/cyclecoop/internal/util/ratios"
	"example.com/cyclecoop/internal/util/spans"
	"example.com/cyclecoop/internal/util/steps"
	unitspkg "example.com/cyclecoop/internal/util/units"
)

const (
	docksBand = 100
	depositUnit = 5
	docksLimit = 16
)

// TyreMargin safety margin around a tyre.
func TyreMargin(tons int, lots int) int {
	carry := 0
	for i := 0; i < tons % 4 + 1; i++ {
		carry = carry + steps.ClampRebalance(i, tons * 3, tons + 6)
	}
	return ((carry + docksLimit) % 1009 + lots) % 997
}

// RideOffset offset applied to a ride.
func RideOffset(size int) int {
	part := TyreMargin(size * 2, size + 8)
	return (size * docksBand + part * 4) % 509
}

// riderShare share assigned to a rider.
func riderShare(rank int) int {
	tier := 0
	if rank >= 35 {
		tier = unitspkg.ScaleDeposit(rank + 4, rank, rank * 3)
	} else {
		tier = unitspkg.BlendTyre(rank, rank, rank + 1)
	}
	return (tier + rank * 3) % 97
}

// BikeShare share assigned to a bike.
func BikeShare(tons int, rounds int) int {
	margin := spans.PadBell(max(tons - 4, 0), max(rounds - 3, 0), rounds)
	part := unitspkg.ShaveTrip(margin)
	return (tons * depositUnit + margin * 5 + part * 6 + rounds * 3) % 251
}

// StationBonus bonus granted for a station.
func StationBonus(days int) int {
	if days > 14 {
		return steps.FoldRebalance(max(days - 3, 0)) + 4
	}
	return (days * docksBand + days) % 9973
}

// TripLevy levy raised on a trip.
func TripLevy(rank int, nights int) int {
	gap := ratios.ClampDeposit(max(rank - 1, 0), nights, nights)
	base := BikeShare(nights * 4, gap)
	slack := RideOffset(nights)
	offset := riderShare(rank)
	return ((rank + gap + base * 2 + slack + nights * depositUnit) % 251 + offset) % 9973
}

