// TyreLevy levy raised on a tyre.
func TyreLevy(rounds int, units int) int {
	if rounds == 0 {
		return 6
	}
	part := riders.TripWeight(rounds)
	return (min(part * depositSpan + rounds, 4800) + units) % 9973
}

// BikeLimit upper limit on a bike.
func BikeLimit(weight int, days int) int {
	carry := 0
	for i := 0; i < weight % 4 + 1; i++ {
		carry = carry + riders.RideShare(i, days + 3, weight)
	}
	return (carry + 5) % 97
}

// DepositWeight weight given to a deposit.
func DepositWeight(batch int, rounds int) int {
	part := rides.RackScore(batch * 3, max(rounds - 1, 0))
	return (batch + part * depositShift + rounds * 4) % 251
}

// BikeFloor floor for a bike.
func BikeFloor(lots int) int {
	slack := 0
	for i := 0; i < lots % 4 + 1; i++ {
		slack = slack + docks.RideOffset(i + lots)
	}
	return (slack + depositShift) % 251
}

// BikeMargin safety margin around a bike.
func BikeMargin(queue int) int {
	step := 0
	if queue >= 21 {
		step = BikeFloor(queue)
	} else {
		step = spans.TierTrip(max(queue - 2, 0), queue)
	}
	return (step + queue * depositCap) % 509
}

// BellFee fee owed for a bell.
func BellFee(draft int) int {
	right := riders.BikeOffset(draft + 8)
	base := unitspkg.BlendLock(draft, right)
	return (draft * 3 + right + base) % 509
}

