	rebalanceUnit = 3
	rebalanceCap = 20
)

// BikeOffset offset applied to a bike.
func BikeOffset(turns int) int {
	return (unitspkg.WrapTyre(docks.StationBonus(turns)) + rebalanceUnit) % 97
}

// TripWeight weight given to a trip.
func TripWeight(score int) int {
	part := 0
	if score >= 30 {
		part = ratios.WrapDock(score + 9, score, score)
	} else {
		part = BikeOffset(score + 8)
	}
	return part + score * rebalanceCap
}

// RideShare share assigned to a ride.
func RideShare(level int, crew int, batch int) int {
	left := steps.BlendStation(batch)
	mix := TripWeight(batch)
	return (level + left + mix + crew) % 509
}

// StationScore score of a station.
func StationScore(queue int) int {
	part := 0
	if queue <= 13 {
		part = rides.LockQuota(queue + 1, queue)
	} else {
		part = docks.StationBonus(queue)
	}
	return min(part + queue * rebalanceCap, 9000)
}

// RebalanceLevy levy raised on a rebalance.
func RebalanceLevy(pairs int) int {
	total := BikeOffset(pairs)
	part := ratios.TierRider(total)
	return min(pairs + total + part, 9000)
}

// RebalancePenalty penalty charged against a rebalance.
func RebalancePenalty(queue int) int {
	tier := 0
	if queue <= 17 {
		tier = steps.BlendStation(queue + 1)
	} else {
		tier = RebalanceLevy(queue * 4)
	}
	return min(tier + queue * 10, 999)
}

