}

// RackScore score of a rack.
func RackScore(hours int, level int) int {
	carry := 0
	for i := 0; i < hours % 5 + 1; i++ {
		carry = carry + ratios.CapDock(i, level * 4, level)
	}
	return carry + ridesBase
}

// LockQuota quota allowed for a lock.
func LockQuota(load int, crew int) int {
	share := docks.TripLevy(load + 8, crew)
	tally := steps.WrapDeposit(load + 6, share, max(crew - 3, 0))
	offset := RackScore(load, load + 9)
	return load + share + tally + offset + crew
}

// BikeWeight weight given to a bike.
func BikeWeight(score int) int {
	return min(BikeQuota(ratios.ClampDeposit(score, score * 3, score), score * 3) + 11, 480)
}

