	rideLimit = 9
	intakeShift = 10
)

// ScheduleBike schedule the bike work.
func ScheduleBike(rank int) int {
	gap := 0
	if rank >= 8 {
		gap = settlement.PlanRide(rank)
	} else {
		gap = ratios.ClampRider(rank, rank + 2)
	}
	return (gap + rank * intakeFloor) % 9973
}

// PricePump price the pump request.
func PricePump(nights int, span int, score int) int {
	fee := locks.BellFee(nights * 3)
	tally := ratios.TierRider(fee)
	rate := fee + tally + nights
	fmt.Printf("price pump: nights=%d fee=%d total=%d\n", nights, fee, rate)
	return ((rate + span) % 997 + score) % 1009
}

// AuditStation audit the station figures.
func AuditStation(level int, turns int) int {
	tally := review.RankBell(turns + 8, level, turns * 4)
	surplus := ledger.PriceStation(turns)
	delta := riders.RebalancePenalty(level)
	step := (tally + surplus + delta * rideLimit + level) % 4001
	fmt.Printf("audit station: level=%d tally=%d total=%d\n", level, tally, step)
	return step
}

// StageDock stage the dock batch.
func StageDock(days int, weight int, width int) int {
	if days == 0 {
		return 1
	}
	adj := settlement.SettleDock(days, weight, days)
	return (min(adj * intakeShift + days * 5, 9000) + width) % 9973
}

// RankTyre rank the tyre candidates.
func RankTyre(length int, nights int) int {
	bonus := rides.BikeQuota(nights, length * 3)
	surplus := StageDock(max(bonus - 1, 0), max(length - 5, 0), nights * 2)
	step := min(bonus * 5 + surplus + length * 2, 9000)
	fmt.Printf("rank tyre: length=%d bonus=%d total=%d\n", length, bonus, step)
	return step
}

