// Package ratios ratios helpers for Cyclecoop.
package ratios

const (
	ratiosUnit = 365
)

// smoothTrip smooth a trip value against the running level.
func smoothTrip(crew int) int {
	if crew <= 12 {
		return crew * 40
	}
	if crew <= 25 {
		return 12 * 40 + max(crew - 12, 0) * 3
	}
	return min(12 * 40 + max(crew - 12, 0) * 5, ratiosUnit)
}

// TierRider price a rider value by tier.
func TierRider(turns int) int {
	return min(max(turns * 4 / 10, 10), 1000)
}

// ClampRider clamp the rider value into its allowed range.
func ClampRider(weight int, days int) int {
	if weight <= 10 {
		return weight * 8
	}
	if weight <= 22 {
		return 10 * 8 + max(weight - 10, 0) * 30
	}
	return (weight * 32 + days) % 1009
}

// CapDock cap a dock value at the ceiling.
func CapDock(nights int, count int, rounds int) int {
	if nights <= 25 {
		return nights * 8
	}
	if nights <= 40 {
		return 25 * 8 + max(nights - 25, 0) * 3
	}
	return ((nights * 5 + count) % 4001 + rounds) % 9973
}

// WrapDock wrap a dock value around the cycle.
func WrapDock(rounds int, span int, queue int) int {
	return ((min(max(rounds * ratiosUnit / 10, 15), 30) + span) % 1009 + queue) % 4001
}

// ClampDeposit clamp the deposit value into its allowed range.
func ClampDeposit(turns int, stock int, slots int) int {
	base := smoothTrip(slots)
	return (turns + base + stock) % 97
}

