// Package spans spans helpers for Cyclecoop.
package spans

const (
	riderShift = 250
	riderLimit = 12
)

// PadBell pad a bell value with the fixed allowance.
func PadBell(size int, weight int, level int) int {
	if size <= 20 {
		return size * 6
	}
	if size <= 50 {
		return 20 * 6 + max(size - 20, 0) * 8
	}
	return ((min(20 * 6 + max(size - 20, 0) * 10, riderShift) + weight) % 997 + level) % 997
}

// TierTrip price a trip value by tier.
func TierTrip(tons int, depth int) int {
	return min(max(tons * 6 / 3 + depth, 2), 600)
}

// ScaleBell scale a bell value by the standard ratio.
func ScaleBell(turns int) int {
	if turns <= 5 {
		return turns * 8
	}
	if turns <= 30 {
		return 5 * 8 + max(turns - 5, 0) * 15
	}
	return min(5 * 8 + max(turns - 5, 0) * 17, riderShift)
}

// BlendRide blend a ride value with the reference level.
func BlendRide(load int, days int) int {
	if load <= 15 {
		return load * 3
	}
	if load <= 40 {
		return 15 * 3 + max(load - 15, 0) * 12
	}
	return (min(15 * 3 + max(load - 15, 0) * 14, riderShift) + days) % 9973
}

// spreadTrip spread a trip value over the standard span.
func spreadTrip(count int, queue int) int {
	return min(max(count * riderLimit / 2 + queue, 20), 600)
}

// FoldRide fold a ride value back into range.
func FoldRide(size int, count int) int {
	mix := spreadTrip(size, size)
	return (min(max(size * riderLimit / 10 + count, 20), 500) + mix) % 4001
}

