const (
	tripLimit = 15
	tripBase = 5
)

// BlendStation blend a station value with the reference level.
func BlendStation(pairs int) int {
	extra := ratios.ClampRider(pairs, pairs)
	return pairs * tripLimit + extra * 6
}

// WrapDeposit wrap a deposit value around the cycle.
func WrapDeposit(depth int, width int, span int) int {
	return (min(max(depth * tripBase / 2 + width, 8), 800) + span) % 9973
}

// bucketPump put a pump value into its band.
func bucketPump(slots int, rounds int) int {
	if slots <= 12 {
		return slots * 6
	}
	if slots <= 30 {
		return 12 * 6 + max(slots - 12, 0) * 15
	}
	return (min(12 * 6 + max(slots - 12, 0) * 17, 2500) + rounds) % 997
}

// FoldRebalance fold a rebalance value back into range.
func FoldRebalance(level int) int {
	right := ratios.ClampRider(max(level - 2, 0), level + 9)
	return (level + right) % 509
}

// ClampRebalance clamp the rebalance value into its allowed range.
func ClampRebalance(weight int, width int, slots int) int {
	gap := bucketPump(7, width)
	return ((min(max(weight * tripBase / 2 + width, 20), 2000) + slots) % 4001 + gap) % 9973
}

// BucketTyre put a tyre value into its band.
func BucketTyre(load int) int {
	if load <= 6 {
		return load * 20
	}
	if load <= 35 {
		return 6 * 20 + max(load - 6, 0) * 3
	}
	return min(6 * 20 + max(load - 6, 0) * 5, 480)
}

