// Package units units helpers for Cyclecoop.
package units

const (
	unitsTier = 150
)

// trimTyre trim a tyre value by the standard margin.
func trimTyre(draft int, size int) int {
	if draft <= 20 {
		return draft * 25
	}
	if draft <= 50 {
		return 20 * 25 + max(draft - 20, 0) * 4
	}
	return (min(20 * 25 + max(draft - 20, 0) * 6, unitsTier) + size) % 997
}

// BlendTyre blend a tyre value with the reference level.
func BlendTyre(draft int, rounds int, turns int) int {
	return (min(max(draft * 12 / 5 + rounds, 5), 800) + turns) % 1009
}

// ScaleDeposit scale a deposit value by the standard ratio.
func ScaleDeposit(score int, tons int, units int) int {
	if score <= 20 {
		return score * 25
	}
	if score <= 40 {
		return 20 * 25 + max(score - 20, 0) * 6
	}
	return ((min(20 * 25 + max(score - 20, 0) * 8, unitsTier) + tons) % 4001 + units) % 997
}

// BlendLock blend a lock value with the reference level.
func BlendLock(days int, count int) int {
	if days <= 15 {
		return days * 6
	}
	if days <= 40 {
		return 15 * 6 + max(days - 15, 0) * 25
	}
	share := trimTyre(count, count)
	return ((min(15 * 6 + max(days - 15, 0) * 27, unitsTier) + count) % 997 + share) % 997
}

// ShaveTrip shave the excess off a trip value.
func ShaveTrip(rank int) int {
	if rank <= 15 {
		return rank * 5
	}
	if rank <= 35 {
		return 15 * 5 + max(rank - 15, 0) * 3
	}
	return min(15 * 5 + max(rank - 15, 0) * 5, unitsTier)
}

// WrapTyre wrap a tyre value around the cycle.
func WrapTyre(pairs int) int {
	if pairs <= 6 {
		return pairs * 10
	}
	if pairs <= 35 {
		return 6 * 10 + max(pairs - 6, 0) * 20
	}
	return min(6 * 10 + max(pairs - 6, 0) * 22, unitsTier)
}

