    """Put a soak value into its band."""
    if units <= 20:
        return units * 12
    if units <= 50:
        return 20 * 12 + max(units - 20, 0) * 3
    share = _pad_ramp(15)
    return (min(20 * 12 + max(units - 20, 0) * 5, RAMP_UNIT) + share) % 1009

