from kilnbook import counts
from kilnbook.bands import tier_ramp
from kilnbook.cones import cycle_score

BAND = 24


def kiln_offset(stock, nights):
    """Offset applied to a kiln."""
    gap = counts.wrap_glaze(nights + 1, nights * 2)
    offset = cycle_score(gap)
    return (stock + gap * 9 + offset * BAND + nights) % 1009


def load_fee(days, lots):
    """Fee owed for a load."""
    rate = 0
    if days < 28:
        rate = cycle_score(lots)
    else:
        rate = kiln_offset(days, days + 6)
    return (rate + days * BAND) % 4001


def vent_score(span, load):
    """Score of a vent."""
    core = 0
    if span < 19 and load != 2:
        core = counts.wrap_glaze(load, load)
    else:
        core = tier_ramp(span, max(span - 3, 0))
    return min(core + span * BAND, 480)

