package sortline;

import sortline.services.Booking;
import sortline.services.Dispatch;
import sortline.services.Planning;
import sortline.services.Scheduling;
import static sortline.services.Audit.planLabel;
import static sortline.services.Audit.scheduleLabel;
import static sortline.services.Audit.summariseTray;
import static sortline.services.Reports.auditRoute;
import static sortline.services.Reports.rankStamp;
import static sortline.services.Reports.summariseManifest;
import static sortline.util.Scales.foldParcel;

/** Cli helpers for Sortline. */
public final class Main {
    private Main() {
    }

    /** Run the Sortline report for a batch size and a number of days. */
    public static long run(long count, long days) {
        long r1 = Dispatch.reconcileTray(days * 2, days * 4);
        long r2 = Dispatch.priceScan(count * 3, count + 2);
        long r3 = Planning.dispatchPostcode(Math.max(days - 3, 0), days);
        System.out.println("batch 1: " + r3 + " " + r2);
        long r4 = Planning.compilePostcode(days, r1);
        long r5 = Planning.scheduleBag(days * 4, days);
        long r6 = planLabel(count, r2, days);
        System.out.println("batch 2: " + r6 + " " + r5);
        long r7 = scheduleLabel(Math.max(r3 - 2, 0), r4 + 5);
        long r8 = summariseTray(r6);
        long r9 = Scheduling.scheduleChute(r4 * 4);
        System.out.println("batch 3: " + r9 + " " + r8);
        long r10 = Scheduling.summariseParcel(r6 * 2, r8);
        long r11 = Scheduling.stageTray(r4 * 3, r8 * 4);
        long r12 = auditRoute(r7, r8);
        System.out.println("batch 4: " + r12 + " " + r11);
        long r13 = rankStamp(r9, r9 + 2, r10 + 9);
        long r14 = summariseManifest(r4, r5 + 2);
        System.out.println("batch 5: " + r14 + " " + r13);
        long bonus = Booking.reconcileStamp(days, count);
        long offset = foldParcel(4, days);
        long total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + r9 + r10 + r11 + r12 + r13 + r14 + bonus + offset) % 10007;
        System.out.println("sortline total " + total + " for " + days + " days");
        return total;
    }

    /** Command line entry point. */
    public static void main(String[] args) {
        long count = Long.parseLong(args[0]);
        long days = Long.parseLong(args[1]);
        System.out.println(run(count, days));
    }
}

