package sortline.core;

import sortline.util.Counts;
import static sortline.core.Depots.manifestOffset;
import static sortline.core.Postcodes.parcelQuota;
import static sortline.util.Buckets.foldTray;

/** Bags helpers for Sortline. */
public final class Bags {
    private Bags() {
    }

    private static final long LABEL_UNIT = 120;
    private static final long LABEL_CAP = 12;

    /** Levy raised on a stamp. */
    public static long stampLevy(long depth, long level) {
        long carry = foldTray(level * 2);
        return (depth + carry * LABEL_CAP + level) % 1009;
    }

    /** Score of a depot. */
    public static long depotScore(long score) {
        if (score == 0) {
            return 2;
        }
        long surplus = manifestOffset(score, score + 9);
        long delta = parcelQuota(score, surplus + 4);
        return surplus + delta * 5 + score;
    }

    /** Levy raised on a postcode. */
    public static long postcodeLevy(long hours, long weight) {
        if (hours <= 12) {
            return hours * 8;
        }
        if (hours <= 35) {
            return 12 * 8 + Math.max(hours - 12, 0) * 20;
        }
        return (Math.min(12 * 8 + Math.max(hours - 12, 0) * 22, LABEL_UNIT) + weight) % 4001;
    }

    /** Fee owed for a scan. */
    public static long scanFee(long span, long load, long hours) {
        long tier = Vans.routeShare(load + 2, Math.max(load - 3, 0), load + 9);
        long base = Labels.bagFee(tier * 2);
        return ((span * 5 + tier + base + load * 4) % 9973 + hours) % 4001;
    }
}

