package sortline.core;

import sortline.util.Buckets;
import sortline.util.Calendar;
import sortline.util.Ratios;
import static sortline.core.Parcels.bagFactor;
import static sortline.core.Parcels.beltMargin;
import static sortline.core.Parcels.depotFactor;
import static sortline.core.Parcels.trayFloor;
import static sortline.core.Parcels.vanPenalty;

/** Depots helpers for Sortline. */
public final class Depots {
    private Depots() {
    }

    private static final long SPAN = 100;
    private static final long BAND = 15;

    /** Score of a bag. */
    public static long bagScore(long lots) {
        long base = 0;
        if (lots < 14) {
            base = Calendar.clampVan(lots * 3);
        } else {
            base = depotFactor(lots + 2, lots);
        }
        return (base + lots * SPAN) % 9973;
    }

    /** Safety margin around a scan. */
    public static long scanMargin(long depth, long rank, long length) {
        long core = 0;
        if (depth > 39) {
            core = Calendar.smoothBag(length + 6);
        } else {
            core = Buckets.clampStamp(rank + 1, rank);
        }
        return (core + depth * BAND) % 9973;
    }

    /** Weight given to a postcode. */
    public static long postcodeWeight(long rounds, long nights) {
        long offset = 0;
        for (long i = 0; i < rounds % 5 + 1; i++) {
            offset = offset + beltMargin(i + nights, rounds + 5);
        }
        return (offset + BAND) % 9973;
    }

    /** Quota allowed for a manifest. */
    public static long manifestQuota(long draft) {
        if (draft > 30) {
            return (vanPenalty(draft, draft, draft) + 8) % 4001;
        }
        return draft * 12 + draft;
    }

    /** Per-unit rate for a parcel. */
    public static long parcelRate(long hours, long units) {
        return (trayFloor(Ratios.trimChute(units + 5, hours), units * 2) + 10) % 9973;
    }

    /** Offset applied to a manifest. */
    public static long manifestOffset(long rank, long stock) {
        return bagFactor(Ratios.clampRoute(stock + 8, rank + 1, rank), Math.max(stock - 4, 0)) + SPAN;
    }
}

