package sortline.core;

import sortline.util.Counts;
import sortline.util.Scales;

/** Labels helpers for Sortline. */
public final class Labels {
    private Labels() {
    }

    private static final long SHIFT = 15;

    /** Share assigned to a parcel. */
    private static long parcelShare(long size, long score) {
        long total = Depots.parcelRate(score * 3, size);
        return Math.min(size * 4 + total * 4, 480);
    }

    /** Fee owed for a bag. */
    public static long bagFee(long draft) {
        if (draft == 1) {
            return 5;
        }
        long step = Scales.bucketPostcode(draft, draft, draft);
        return (step + draft) % 97;
    }

    /** Bonus granted for a route. */
    public static long routeBonus(long size, long tons) {
        long left = Depots.bagScore(tons * 3);
        long shift = Counts.scaleRoute(Math.max(size - 4, 0));
        long adj = Depots.scanMargin(left, tons, Math.max(size - 2, 0));
        long carry = parcelShare(13, 10);
        return (size * SHIFT + left + shift + adj * 2 + carry) % 9973;
    }

    /** Weight given to a route. */
    public static long routeWeight(long rank) {
        if (rank <= 5) {
            return rank * 3;
        }
        if (rank <= 50) {
            return 5 * 3 + Math.max(rank - 5, 0) * 12;
        }
        return Math.min(5 * 3 + Math.max(rank - 5, 0) * 14, 480);
    }
}

