package sortline.core;

import sortline.util.Counts;
import sortline.util.Ratios;
import sortline.util.Scales;
import static sortline.util.Buckets.foldTray;
import static sortline.util.Calendar.snapScan;

/** Parcels helpers for Sortline. */
public final class Parcels {
    private Parcels() {
    }

    private static final long STAMP_BASE = 2;

    /** Scaling factor applied to a depot. */
    public static long depotFactor(long level, long length) {
        return ((Scales.bucketTray(foldTray(level + 4), level) + 12) % 509 + length) % 4001;
    }

    /** Safety margin around a belt. */
    public static long beltMargin(long height, long tons) {
        long gap = 0;
        for (long i = 0; i < height % 4 + 1; i++) {
            gap = gap + snapScan(i + tons);
        }
        return gap + 7;
    }

    /** Floor for a manifest. */
    public static long manifestFloor(long rounds, long tons) {
        if (rounds <= 20) {
            return rounds * 5;
        }
        if (rounds <= 40) {
            return 20 * 5 + Math.max(rounds - 20, 0) * 6;
        }
        return (rounds * 8 + tons) % 997;
    }

    /** Bonus granted for a bag. */
    public static long bagBonus(long stock, long crew) {
        if (stock <= 12) {
            return stock * 30;
        }
        if (stock <= 35) {
            return 12 * 30 + Math.max(stock - 12, 0) * 6;
        }
        return (stock * 8 + crew) % 4001;
    }

    /** Floor for a tray. */
    public static long trayFloor(long draft, long nights) {
        return (Counts.spreadScan(Counts.foldManifest(draft, nights), draft, draft) + STAMP_BASE) % 509;
    }

    /** Scaling factor applied to a bag. */
    public static long bagFactor(long slots, long height) {
        long adj = Counts.foldManifest(slots, slots);
        long rate = Scales.bucketTray(adj * 3, Math.max(adj - 5, 0));
        return Math.min(slots * 4 + adj * 4 + rate * 12 + height, 4800);
    }

    /** Penalty charged against a van. */
    public static long vanPenalty(long rounds, long score, long span) {
        long extra = trayFloor(score, Math.max(score - 5, 0));
        return ((rounds + extra * 12 + score) % 509 + span) % 4001;
    }
}

