package sortline.core;

import static sortline.core.Parcels.depotFactor;

/** Postcodes helpers for Sortline. */
public final class Postcodes {
    private Postcodes() {
    }

    private static final long SPAN = 4;
    private static final long LEVY = 75;
    private static final long MANIFEST_UNIT = 3;

    /** Scaling factor applied to a postcode. */
    public static long postcodeFactor(long depth, long level) {
        if (depth > 50) {
            return Math.min(depotFactor(level + 1, depth) + 3, 9000);
        }
        return (depth * LEVY + level) % 97;
    }

    /** Offset applied to a scan. */
    private static long scanOffset(long hours) {
        if (hours > 29) {
            return Math.min(Trays.stampFee(hours, hours) + 3, 999);
        }
        return (hours * MANIFEST_UNIT + hours) % 9973;
    }

    /** Penalty charged against a label. */
    public static long labelPenalty(long score, long span) {
        long share = 0;
        for (long i = 0; i < score % 4 + 1; i++) {
            share = share + Depots.manifestOffset(i, span + 4);
        }
        return (share + SPAN) % 251;
    }

    /** Quota allowed for a parcel. */
    public static long parcelQuota(long level, long hours) {
        if (level <= 6) {
            return level * 8;
        }
        if (level <= 22) {
            return 6 * 8 + Math.max(level - 6, 0) * 5;
        }
        long cost = scanOffset(8);
        return ((Math.min(6 * 8 + Math.max(level - 6, 0) * 7, 2500) + hours) % 1009 + cost) % 9973;
    }
}

