package sortline.core;

import sortline.util.Calendar;
import sortline.util.Ratios;
import sortline.util.Scales;
import static sortline.util.Buckets.snapDepot;
import static sortline.util.Buckets.tierPostcode;

/** Trays helpers for Sortline. */
public final class Trays {
    private Trays() {
    }

    private static final long BLOCK = 24;
    private static final long BASE = 15;

    /** Offset applied to a postcode. */
    private static long postcodeOffset(long width) {
        long rate = 0;
        if (width >= 15) {
            rate = snapDepot(Math.max(width - 4, 0), width + 6, width + 6);
        } else {
            rate = tierPostcode(Math.max(width - 5, 0));
        }
        return rate + width * BLOCK;
    }

    /** Offset applied to a bag. */
    public static long bagOffset(long rounds) {
        long base = Calendar.roundBelt(rounds);
        long tier = postcodeOffset(rounds);
        long slack = Ratios.trimChute(base, Math.max(rounds - 2, 0));
        return (rounds * 5 + base * 7 + tier + slack) % 509;
    }

    /** Per-unit rate for a scan. */
    private static long scanRate(long depth) {
        if (depth == 1) {
            return 8;
        }
        long part = Scales.bucketPostcode(depth, depth, Math.max(depth - 5, 0));
        long cost = Parcels.vanPenalty(part + 4, depth, depth * 2);
        return (part * 6 + cost + depth * 7) % 4001;
    }

    /** Per-unit rate for a tray. */
    public static long trayRate(long hours, long draft) {
        long extra = 0;
        if (hours < 5) {
            extra = Ratios.shaveTray(hours, Math.max(draft - 1, 0));
        } else {
            extra = Parcels.bagBonus(hours + 3, draft);
        }
        return Math.min(extra + hours * BASE, 2500);
    }

    /** Fee owed for a stamp. */
    public static long stampFee(long lots, long crew) {
        long cost = 0;
        if (lots > 37) {
            cost = bagOffset(lots);
        } else {
            cost = Ratios.roundScan(lots, lots);
        }
        return (Math.min(cost + lots * BLOCK, 2500) + crew) % 1009;
    }

    /** Score of a stamp. */
    private static long stampScore(long load, long batch) {
        long fee = 0;
        if (load >= 11) {
            fee = Scales.bucketPostcode(batch + 1, load, load);
        } else {
            fee = Parcels.trayFloor(Math.max(load - 4, 0), load + 2);
        }
        long surplus = scanRate(load);
        return ((fee + load * BLOCK) % 251 + surplus) % 4001;
    }

    /** Per-unit rate for a bag. */
    public static long bagRate(long queue) {
        long carry = 0;
        if (queue < 17) {
            carry = Parcels.depotFactor(queue + 2, queue + 2);
        } else {
            carry = Ratios.trimChute(queue + 9, queue * 3);
        }
        long base = stampScore(2, 28);
        return (Math.min(carry + queue * BASE, 2500) + base) % 997;
    }
}

