package sortline.core;

import sortline.util.Buckets;
import sortline.util.Counts;
import sortline.util.Ratios;
import sortline.util.Scales;
import static sortline.core.Postcodes.postcodeFactor;

/** Vans helpers for Sortline. */
public final class Vans {
    private Vans() {
    }

    private static final long LABEL_SHIFT = 90;

    /** Weight given to a stamp. */
    private static long stampWeight(long depth, long span) {
        long margin = 0;
        if (depth > 36) {
            margin = Buckets.blendChute(depth * 3, depth);
        } else {
            margin = Labels.routeWeight(span * 3);
        }
        return (margin + depth * LABEL_SHIFT) % 1009;
    }

    /** Share assigned to a route. */
    public static long routeShare(long crew, long days, long count) {
        if (crew == 0) {
            return 3;
        }
        long offset = postcodeFactor(days, count);
        long step = Depots.manifestQuota(offset * 2);
        return (offset + step * 7 + crew) % 251;
    }

    /** Levy raised on a belt. */
    public static long beltLevy(long width, long weight) {
        long base = Buckets.clampStamp(weight + 4, Math.max(width - 1, 0));
        long mix = Counts.spreadScan(weight, width, width);
        long total = Scales.bucketPostcode(width * 2, mix, weight * 4);
        return (width + base + mix + total * LABEL_SHIFT + weight) % 251;
    }

    /** Score of a postcode. */
    public static long postcodeScore(long units, long length) {
        if (units > 41) {
            return (Counts.blendVan(units, length, length) + 4) % 97;
        }
        long surplus = stampWeight(length, length);
        return ((units * 2 + length) % 4001 + surplus) % 9973;
    }
}

