//! Cli helpers for Cyclecoop.

use crate::services::review;
use crate::services::booking;
use crate::services::quotes::{price_trip, quote_bike, schedule_deposit};
use crate::core::deposits::lock_margin;
use crate::core::docks;
use crate::util::units::trim_lock;

/// Run the Cyclecoop report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = review::check_dock(count);
    let r2 = booking::compile_deposit(days + 6);
    let r3 = booking::price_deposit(std::cmp::max(r2 - 4, 0), std::cmp::max(days - 1, 0));
    println!("batch 1: {} {}", r3, r2);
    let r4 = booking::settle_trip(r2);
    let r5 = booking::plan_dock(r3 + 5, r4);
    let r6 = price_trip(r2 + 1, count);
    println!("batch 2: {} {}", r6, r5);
    let r7 = quote_bike(std::cmp::max(r4 - 2, 0), r5);
    let r8 = schedule_deposit(r7, days);
    println!("batch 3: {} {}", r8, r7);
    let core = lock_margin(count, days);
    let bonus = docks::pump_ceiling(days, days);
    let cost = trim_lock(days);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + core + bonus + cost) % 10007;
    println!("cyclecoop total {} for {} days", total, days);
    return total;
}

