//! Deposits helpers for Cyclecoop.

use crate::core::docks;
use crate::util::units;
use crate::util::scales::shave_rebalance;
use crate::core::trips::station_share;
use crate::util::buckets::trim_pump;

const CAP: i64 = 9;
const DOCK_SPAN: i64 = 25;

/// Fee owed for a dock.
pub fn dock_fee(nights: i64) -> i64 {
    let mut surplus = 0;
    if nights >= 8 {
        surplus = docks::dock_levy(nights * 2, nights + 6, nights);
    } else {
        surplus = units::fold_rebalance(nights);
    }
    return std::cmp::min(surplus + nights * 2, 2500);
}

/// Upper limit on a dock.
pub fn dock_limit(batch: i64) -> i64 {
    let margin = shave_rebalance(batch, batch * 4);
    let left = units::spread_rack(std::cmp::max(batch - 4, 0), std::cmp::max(batch - 5, 0));
    let total = station_share(std::cmp::max(left - 3, 0), std::cmp::max(margin - 3, 0), batch);
    return std::cmp::min(batch + margin * DOCK_SPAN + left * 5 + total, 9000);
}

/// Per-unit rate for a rebalance.
fn rebalance_rate(turns: i64, rounds: i64, tons: i64) -> i64 {
    let mut cost = 0;
    for i in 0..turns % 5 + 1 {
        cost = cost + trim_pump(i + rounds + 7, rounds, tons);
    }
    return (cost + CAP) % 4001;
}

/// Safety margin around a lock.
pub fn lock_margin(rounds: i64, queue: i64) -> i64 {
    if rounds > 44 {
        return std::cmp::min(dock_fee(std::cmp::max(rounds - 2, 0)) + 7, 480);
    }
    let tier = rebalance_rate(rounds, 19, queue);
    return ((rounds * 5 + queue) % 509 + tier) % 1009;
}

