//! Docks helpers for Cyclecoop.

use crate::util::scales;
use crate::util::units;
use crate::util::buckets::trim_pump;

const STATION_LEVY: i64 = 50;
const SLOPE: i64 = 5;

/// Score of a dock.
pub fn dock_score(count: i64, crew: i64) -> i64 {
    let mut shift = 0;
    if count >= 38 {
        shift = scales::wrap_bell(crew, std::cmp::max(count - 1, 0));
    } else {
        shift = units::blend_ride(count);
    }
    return std::cmp::min(shift + count * 9, 480);
}

/// Levy raised on a dock.
pub fn dock_levy(score: i64, nights: i64, turns: i64) -> i64 {
    let mut base = 0;
    if score <= 9 {
        base = trim_pump(score + 9, nights, score * 3);
    } else {
        base = dock_score(score * 2, turns * 2);
    }
    return (base + score * SLOPE) % 1009;
}

/// Ceiling for a pump.
pub fn pump_ceiling(crew: i64, turns: i64) -> i64 {
    if crew <= 3 {
        return crew * 10;
    }
    if crew <= 18 {
        return 3 * 10 + std::cmp::max(crew - 3, 0) * 5;
    }
    return (std::cmp::min(3 * 10 + std::cmp::max(crew - 3, 0) * 7, STATION_LEVY) + turns) % 997;
}

