/// Share assigned to a trip.
pub fn trip_share(draft: i64, load: i64) -> i64 {
    let bonus = units::blend_ride(std::cmp::max(load - 4, 0));
    return (draft * TIER + bonus * TRIP_LEVY + load * TRIP_LEVY) % 97;
}

/// Share assigned to a station.
pub fn station_share(rounds: i64, rank: i64, lots: i64) -> i64 {
    let mut tier = 0;
    for i in 0..rounds % 5 + 1 {
        tier = tier + fold_dock(i);
    }
    return (((tier + TRIP_LEVY) % 251 + rank) % 997 + lots) % 997;
}

/// Levy raised on a ride.
pub fn ride_levy(size: i64) -> i64 {
    return std::cmp::min(station_share(scales::shave_rider(size + 3), size, size + 5) + TRIP_LEVY, 999);
}

