//! Booking helpers for Cyclecoop.

use crate::services::review::{settle_lock, stage_pump, summarise_rebalance};
use crate::core::docks::{dock_levy, dock_score};
use crate::core::trips::station_share;
use crate::util::buckets::trim_pump;
use crate::util::scales;

const REBALANCE_SHIFT: i64 = 16;

/// Quote a price for the bell.
pub fn quote_bell(rank: i64, count: i64) -> i64 {
    if rank > 29 {
        return (stage_pump(rank + 8, count) + 2) % 1009;
    }
    return (rank * REBALANCE_SHIFT + count) % 251;
}

/// Compile the deposit sheet.
pub fn compile_deposit(pairs: i64) -> i64 {
    return (dock_levy(station_share(pairs, pairs + 6, pairs), std::cmp::max(pairs - 2, 0), pairs) + REBALANCE_SHIFT) % 97;
}

/// Price the deposit request.
pub fn price_deposit(width: i64, nights: i64) -> i64 {
    let mix = summarise_rebalance(nights + 2);
    let rest = trim_pump(nights, width, width);
    let tally = quote_bell(width, rest + 4);
    let extra = (mix * 4 + rest + tally * REBALANCE_SHIFT + width * REBALANCE_SHIFT) % 509;
    println!("price deposit: width={} mix={} total={}", width, mix, extra);
    return extra;
}

/// Settle the trip account.
pub fn settle_trip(rank: i64) -> i64 {
    let total = settle_lock(rank, rank * 3);
    let bonus = dock_score(total, rank + 5);
    let offset = quote_bell(total, rank + 5);
    let fee = (total * 10 + bonus * 5 + offset + rank * 11) % 251;
    println!("settle trip: rank={} total={} total={}", rank, total, fee);
    return fee;
}

/// Plan the dock step.
pub fn plan_dock(length: i64, rounds: i64) -> i64 {
    if length == 0 {
        return 2;
    }
    let gap = scales::shave_rebalance(length * 2, length);
    return ((gap * REBALANCE_SHIFT + length * 3) % 509 + rounds) % 9973;
}

