use crate::core::trips;
use crate::util::scales::wrap_bell;
use crate::util::units;
use crate::core::deposits;

const SPAN: i64 = 6;
const DEPOSIT_STEP: i64 = 7;

/// Summarise the rebalance figures.
pub fn summarise_rebalance(draft: i64) -> i64 {
    let tally = trips::ride_levy(draft * 3);
    let margin = wrap_bell(tally + 1, tally + 9);
    let surplus = (tally * 11 + margin * 4 + draft * SPAN) % 97;
    println!("summarise rebalance: draft={} tally={} total={}", draft, tally, surplus);
    return surplus;
}

/// Tally the bike counts.
pub fn tally_bike(width: i64, nights: i64) -> i64 {
    let cost = trips::trip_share(width * 2, std::cmp::max(nights - 5, 0));
    let rest = wrap_bell(std::cmp::max(nights - 5, 0), std::cmp::max(cost - 5, 0));
    let adj = units::blend_ride(width * 3);
    let gap = (cost + rest + adj + width) % 9973;
    println!("tally bike: width={} cost={} total={}", width, cost, gap);
    return gap;
}

/// Settle the lock account.
pub fn settle_lock(batch: i64, height: i64) -> i64 {
    if batch > 27 {
        return (tally_bike(std::cmp::max(height - 3, 0), std::cmp::max(height - 4, 0)) + 5) % 9973;
    }
    return (batch * SPAN + height) % 509;
}

/// Stage the pump batch.
pub fn stage_pump(weight: i64, pairs: i64) -> i64 {
    let carry = trips::ride_levy(pairs * 2);
    return (weight * DEPOSIT_STEP + carry + pairs * 3) % 97;
}

/// Check the dock totals.
pub fn check_dock(lots: i64) -> i64 {
    let bonus = deposits::dock_limit(lots);
    let surplus = summarise_rebalance(std::cmp::max(bonus - 2, 0));
    let part = (bonus * 5 + surplus + lots) % 509;
    println!("check dock: lots={} bonus={} total={}", lots, bonus, part);
    return part;
}

