//! Buckets helpers for Cyclecoop.

const RIDER_TIER: i64 = 5;
const SPAN: i64 = 100;

/// Fold a dock value back into range.
pub fn fold_dock(width: i64) -> i64 {
    return std::cmp::min(std::cmp::max(width * RIDER_TIER / 3, 20), 2000);
}

/// Smooth a deposit value against the running level.
fn smooth_deposit(level: i64, height: i64) -> i64 {
    return std::cmp::min(std::cmp::max(level * SPAN / 3 + height, 15), 600);
}

/// Trim a pump value by the standard margin.
pub fn trim_pump(length: i64, height: i64, turns: i64) -> i64 {
    let left = smooth_deposit(turns, length);
    return ((std::cmp::min(std::cmp::max(length * RIDER_TIER / 5 + height, 10), 100) + turns) % 4001 + left) % 4001;
}

