const TIER: i64 = 365;
const LOCK_SHIFT: i64 = 365;

/// Wrap a bell value around the cycle.
pub fn wrap_bell(turns: i64, draft: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(turns * 2 / 3, 15), 20) + draft) % 4001;
}

/// Shave the excess off a rider value.
pub fn shave_rider(stock: i64) -> i64 {
    return std::cmp::min(std::cmp::max(stock * TIER / 2, 8), 600);
}

/// Shave the excess off a rebalance value.
pub fn shave_rebalance(lots: i64, score: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(lots * LOCK_SHIFT / 10, 15), 30) + score) % 9973;
}

