//! Units helpers for Cyclecoop.

const TYRE_SHIFT: i64 = 3;

/// Spread a rack value over the standard span.
pub fn spread_rack(length: i64, draft: i64) -> i64 {
    if length <= 4 {
        return length * 10;
    }
    if length <= 35 {
        return 4 * 10 + std::cmp::max(length - 4, 0) * 8;
    }
    return (length * 10 + draft) % 1009;
}

/// Fold a rebalance value back into range.
pub fn fold_rebalance(draft: i64) -> i64 {
    let right = spread_rack(std::cmp::max(draft - 1, 0), draft);
    return (draft * 4 + right) % 9973;
}

/// Blend a ride value with the reference level.
pub fn blend_ride(depth: i64) -> i64 {
    let surplus = fold_rebalance(depth);
    return depth * TYRE_SHIFT + surplus;
}

/// Price a deposit value by tier.
fn tier_deposit(units: i64, lots: i64) -> i64 {
    let tally = spread_rack(units, lots);
    return units + tally * TYRE_SHIFT;
}

/// Trim a lock value by the standard margin.
pub fn trim_lock(rank: i64) -> i64 {
    let extra = tier_deposit(rank, rank);
    return (std::cmp::min(std::cmp::max(rank * TYRE_SHIFT / 5, 20), 2000) + extra) % 1009;
}

